import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { 
  getRiskScore, 
  getRecommendation, 
  getConsistencyAnalysis 
} from '../api/api';
import SimpleButton from '../components/SimpleButton';

const SimpleDashboard = () => {
  const navigate = useNavigate();
  const [companyData, setCompanyData] = useState(null);
  const [riskAnalysis, setRiskAnalysis] = useState(null);
  const [recommendation, setRecommendation] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    const loadData = async () => {
      try {
        console.log('Dashboard: Loading data from localStorage...');
        const storedCompanyData = localStorage.getItem('companyData');
        console.log('Dashboard: Raw stored data:', storedCompanyData);

        if (!storedCompanyData) {
          console.log('Dashboard: No company data found, redirecting...');
          navigate('/');
          return;
        }

        const companyData = JSON.parse(storedCompanyData);
        console.log('Dashboard: Parsed company data:', companyData);
        setCompanyData(companyData);

        // Check if we have AI analysis from the upload
        if (companyData.ai_analysis) {
          console.log('Dashboard: Using AI analysis from upload');
          const aiAnalysis = companyData.ai_analysis;

          // Set risk analysis from AI results
          if (aiAnalysis.risk_analysis) {
            setRiskAnalysis(aiAnalysis.risk_analysis);
            console.log('Dashboard: AI Risk analysis set:', aiAnalysis.risk_analysis);
          }

          // Set recommendation from loan analysis
          if (aiAnalysis.loan_analysis) {
            setRecommendation({
              decision: aiAnalysis.decision_result?.decision || 'Conditional Approval',
              loan_limit: aiAnalysis.loan_analysis?.approved_loan_amount || 50000000,
              interest_rate: aiAnalysis.loan_analysis?.interest_rate || 11.5,
              confidence_score: aiAnalysis.decision_result?.confidence_score || 0.7
            });
            console.log('Dashboard: AI Loan analysis set:', aiAnalysis.loan_analysis);
          }
        } else {
          console.log('Dashboard: No AI analysis found, using API calls');
          // Fallback to API calls for backward compatibility

          // Load risk analysis
          console.log('Dashboard: Loading risk analysis...');
          const riskResponse = await getRiskScore();
          console.log('Dashboard: Risk response:', riskResponse);
          if (riskResponse.status === 'success') {
            setRiskAnalysis(riskResponse.risk_analysis);
            console.log('Dashboard: Risk analysis set:', riskResponse.risk_analysis);
          } else {
            console.error('Dashboard: Risk analysis failed:', riskResponse);
          }

          // Load recommendation
          console.log('Dashboard: Loading recommendation...');
          const recResponse = await getRecommendation();
          console.log('Dashboard: Recommendation response:', recResponse);
          if (recResponse.status === 'success') {
            setRecommendation(recResponse.recommendation);
            console.log('Dashboard: Recommendation set:', recResponse.recommendation);
          } else {
            console.error('Dashboard: Recommendation failed:', recResponse);
          }
        }
      } catch (err) {
        console.error('Dashboard: Error loading data:', err);
        setError('Failed to load dashboard data: ' + err.message);
      } finally {
        setLoading(false);
      }
    };

    loadData();
  }, [navigate]);

  const formatCurrency = (amount) => {
    if (amount >= 10000000) {
      return `₹${(amount / 10000000).toFixed(2)} Cr`;
    } else if (amount >= 100000) {
      return `₹${(amount / 100000).toFixed(2)} L`;
    } else {
      return `₹${amount.toLocaleString()}`;
    }
  };

  const getRecommendationColor = (decision) => {
    switch (decision?.toLowerCase()) {
      case 'approve':
        return 'text-green-600 bg-green-100';
      case 'conditional approval':
        return 'text-yellow-600 bg-yellow-100';
      case 'reject':
        return 'text-red-600 bg-red-100';
      default:
        return 'text-gray-600 bg-gray-100';
    }
  };

  const getRiskCategoryColor = (category) => {
    switch (category?.toLowerCase()) {
      case 'very high':
        return 'text-red-600 bg-red-100';
      case 'high':
        return 'text-orange-600 bg-orange-100';
      case 'medium':
        return 'text-yellow-600 bg-yellow-100';
      case 'low':
        return 'text-blue-600 bg-blue-100';
      case 'very low':
        return 'text-green-600 bg-green-100';
      default:
        return 'text-gray-600 bg-gray-100';
    }
  };

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600 mx-auto mb-4"></div>
          <p className="text-lg text-gray-600">Loading your credit analysis...</p>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <div className="text-center">
          <div className="text-6xl mb-4">⚠️</div>
          <h2 className="text-2xl font-bold text-red-600 mb-2">Error Loading Dashboard</h2>
          <p className="text-gray-600">{error}</p>
          <SimpleButton onClick={() => window.location.reload()} className="mt-6">
            Try Again
          </SimpleButton>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-blue-50 via-indigo-50 to-purple-50">
      {/* Header with gradient background */}
      <div className="bg-gradient-to-r from-blue-600 to-indigo-700 text-white shadow-xl">
        <div className="max-w-7xl mx-auto px-4 py-8">
          <div className="flex items-center justify-between">
            <div>
              <h1 className="text-4xl font-bold mb-2 flex items-center">
                <span className="mr-3">🏦</span>
                AI Credit Analysis Dashboard
              </h1>
              <p className="text-xl text-blue-100">
                {companyData?.company || 'Company'} - Comprehensive Risk Assessment
              </p>
              <div className="mt-2 flex items-center space-x-4">
                <span className="bg-white/20 px-3 py-1 rounded-full text-sm">
                  📊 Dynamic Analysis
                </span>
                <span className="bg-white/20 px-3 py-1 rounded-full text-sm">
                  🤖 AI-Powered
                </span>
                <span className="bg-white/20 px-3 py-1 rounded-full text-sm">
                  ⚡ Real-time
                </span>
              </div>
            </div>
            <div className="flex space-x-3">
              <SimpleButton
                onClick={() => navigate('/research')}
                className="bg-white text-blue-600 hover:bg-blue-50 font-semibold px-6 py-3 rounded-lg shadow-lg"
              >
                📈 Research Insights
              </SimpleButton>
              <SimpleButton
                onClick={() => navigate('/cam-preview')}
                className="bg-green-500 text-white hover:bg-green-600 font-semibold px-6 py-3 rounded-lg shadow-lg"
              >
                📄 Generate CAM
              </SimpleButton>
            </div>
          </div>
        </div>
      </div>

      <div className="max-w-7xl mx-auto px-4 py-8">
        {/* Key Metrics with enhanced cards */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-8">
          <div className="bg-white rounded-xl shadow-lg p-6 text-center transform hover:scale-105 transition-all duration-200 border border-gray-100">
            <div className="text-6xl mb-4">🛡️</div>
            <h3 className="text-lg font-semibold text-gray-900 mb-1">Risk Score</h3>
            <div className="text-3xl font-bold bg-gradient-to-r from-blue-600 to-indigo-600 bg-clip-text text-transparent">
              {riskAnalysis?.risk_score || 0}
              <span className="text-lg text-gray-500">/100</span>
            </div>
            <div className={`mt-2 px-3 py-1 rounded-full text-sm font-medium ${getRiskCategoryColor(riskAnalysis?.risk_category)}`}>
              {riskAnalysis?.risk_category || 'Unknown'}
            </div>
            <div className="mt-3 text-xs text-gray-500">
              AI-Calculated Risk Assessment
            </div>
          </div>

          <div className="bg-white rounded-xl shadow-lg p-6 text-center transform hover:scale-105 transition-all duration-200 border border-gray-100">
            <div className="text-6xl mb-4">✅</div>
            <h3 className="text-lg font-semibold text-gray-900 mb-1">Decision</h3>
            <div className={`text-2xl font-bold ${getRecommendationColor(recommendation?.decision)}`}>
              {recommendation?.decision || 'Pending'}
            </div>
            <div className="mt-3 text-xs text-gray-500">
              Intelligent Credit Decision
            </div>
          </div>

          <div className="bg-white rounded-xl shadow-lg p-6 text-center transform hover:scale-105 transition-all duration-200 border border-gray-100">
            <div className="text-6xl mb-4">💰</div>
            <h3 className="text-lg font-semibold text-gray-900 mb-1">Loan Limit</h3>
            <div className="text-2xl font-bold bg-gradient-to-r from-green-600 to-emerald-600 bg-clip-text text-transparent">
              {formatCurrency(recommendation?.loan_limit || 0)}
            </div>
            <div className="mt-3 text-xs text-gray-500">
              AI-Calculated Affordability
            </div>
          </div>

          <div className="bg-white rounded-xl shadow-lg p-6 text-center transform hover:scale-105 transition-all duration-200 border border-gray-100">
            <div className="text-6xl mb-4">📈</div>
            <h3 className="text-lg font-semibold text-gray-900 mb-1">Interest Rate</h3>
            <div className="text-2xl font-bold bg-gradient-to-r from-orange-600 to-red-600 bg-clip-text text-transparent">
              {recommendation?.interest_rate || 0}%
            </div>
            <div className="mt-3 text-xs text-gray-500">
              Risk-Based Pricing
            </div>
          </div>
        </div>

        {/* Financial Overview with enhanced styling */}
        {companyData && (
          <div className="bg-white rounded-xl shadow-lg p-8 mb-8 border border-gray-100">
            <h3 className="text-2xl font-bold text-gray-900 mb-6 flex items-center">
              <span className="mr-3">📊</span>
              Financial Overview
            </h3>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
              <div className="bg-gradient-to-br from-blue-50 to-blue-100 p-6 rounded-xl border border-blue-200">
                <p className="text-sm text-blue-600 font-medium mb-2">Revenue</p>
                <p className="text-2xl font-bold text-blue-900">
                  {formatCurrency(companyData.revenue || 0)}
                </p>
                <div className="mt-2 text-xs text-blue-600">Annual Revenue</div>
              </div>
              <div className="bg-gradient-to-br from-green-50 to-green-100 p-6 rounded-xl border border-green-200">
                <p className="text-sm text-green-600 font-medium mb-2">Profit</p>
                <p className="text-2xl font-bold text-green-900">
                  {formatCurrency(companyData.profit || 0)}
                </p>
                <div className="mt-2 text-xs text-green-600">Net Profit</div>
              </div>
              <div className="bg-gradient-to-br from-purple-50 to-purple-100 p-6 rounded-xl border border-purple-200">
                <p className="text-sm text-purple-600 font-medium mb-2">Assets</p>
                <p className="text-2xl font-bold text-purple-900">
                  {formatCurrency(companyData.assets || 0)}
                </p>
                <div className="mt-2 text-xs text-purple-600">Total Assets</div>
              </div>
              <div className="bg-gradient-to-br from-orange-50 to-orange-100 p-6 rounded-xl border border-orange-200">
                <p className="text-sm text-orange-600 font-medium mb-2">Liabilities</p>
                <p className="text-2xl font-bold text-orange-900">
                  {formatCurrency(companyData.liabilities || 0)}
                </p>
                <div className="mt-2 text-xs text-orange-600">Total Liabilities</div>
              </div>
            </div>
          </div>
        )}

        {/* AI-Generated Risk Factors with enhanced styling */}
        {(companyData?.ai_analysis?.risk_factors || riskAnalysis?.risk_factors) && (
          <div className="bg-white rounded-xl shadow-lg p-8 mb-8 border border-gray-100">
            <h3 className="text-2xl font-bold text-gray-900 mb-6 flex items-center">
              <span className="mr-3">🤖</span>
              AI-Generated Key Risk Factors
            </h3>
            <div className="space-y-3">
              {(companyData?.ai_analysis?.risk_factors || riskAnalysis?.risk_factors || []).slice(0, 5).map((factor, index) => {
                // Handle both string and object formats
                const factorText = typeof factor === 'string' ? factor : factor.description;
                const severity = typeof factor === 'object' ? factor.severity : 'Medium';
                const category = typeof factor === 'object' ? factor.category : 'Risk';

                const getSeverityColor = (severity) => {
                  switch (severity?.toLowerCase()) {
                    case 'critical': return 'bg-red-50 border-red-400 text-red-800';
                    case 'high': return 'bg-orange-50 border-orange-400 text-orange-800';
                    case 'medium': return 'bg-yellow-50 border-yellow-400 text-yellow-800';
                    case 'low': return 'bg-blue-50 border-blue-400 text-blue-800';
                    default: return 'bg-gray-50 border-gray-400 text-gray-800';
                  }
                };

                const getIcon = (severity) => {
                  switch (severity?.toLowerCase()) {
                    case 'critical': return '🚨';
                    case 'high': return '⚠️';
                    case 'medium': return '⚡';
                    case 'low': return 'ℹ️';
                    default: return '⚠️';
                  }
                };

                return (
                  <div
                    key={index}
                    className={`flex items-start space-x-3 p-4 rounded-xl border-l-4 ${getSeverityColor(severity)} transform hover:scale-102 transition-all duration-200`}
                  >
                    <div className="text-2xl">{getIcon(severity)}</div>
                    <div className="flex-1">
                      <div className="flex items-center justify-between mb-2">
                        <p className="text-xs font-medium uppercase tracking-wide">{category}</p>
                        <span className={`text-xs px-2 py-1 rounded-full ${getSeverityColor(severity)}`}>
                          {severity}
                        </span>
                      </div>
                      <p className="text-sm font-medium">{factorText}</p>
                      {typeof factor === 'object' && factor.recommendation && (
                        <p className="text-xs mt-1 opacity-75">💡 {factor.recommendation}</p>
                      )}
                    </div>
                  </div>
                );
              })}
              {(!companyData?.ai_analysis?.risk_factors && !riskAnalysis?.risk_factors) && (
                <div className="text-center py-8">
                  <div className="text-4xl mb-4">✅</div>
                  <p className="text-gray-600">No significant risk factors identified</p>
                </div>
              )}
            </div>
            {companyData?.ai_analysis?.risk_factors && (
              <div className="mt-4 text-xs text-gray-500 text-center bg-blue-50 p-3 rounded-lg">
                🤖 AI-powered risk analysis based on financial metrics and market research
              </div>
            )}
          </div>
        )}

        {/* AI Decision Reasoning with enhanced styling */}
        {companyData?.ai_analysis?.decision_result && (
          <div className="bg-white rounded-xl shadow-lg p-8 mb-8 border border-gray-100">
            <h3 className="text-2xl font-bold text-gray-900 mb-6 flex items-center">
              <span className="mr-3">🧠</span>
              AI Decision Analysis & Reasoning
            </h3>
            <div className="space-y-4">
              <div className="bg-gradient-to-r from-blue-50 to-indigo-50 p-6 rounded-xl border border-blue-200">
                <div className="flex items-center justify-between mb-3">
                  <h4 className="font-semibold text-blue-900 text-lg">Decision</h4>
                  <span className={`px-4 py-2 rounded-full text-sm font-bold ${getRecommendationColor(companyData.ai_analysis.decision_result.decision)}`}>
                    {companyData.ai_analysis.decision_result.decision}
                  </span>
                </div>
                <div className="text-sm text-blue-700">
                  Confidence: {(companyData.ai_analysis.decision_result.confidence_score * 100).toFixed(1)}%
                </div>
              </div>

              <div className="bg-gray-50 p-6 rounded-xl border border-gray-200">
                <h4 className="font-semibold text-gray-900 mb-4 text-lg">Key Factors Influencing Decision</h4>
                <ul className="space-y-3">
                  {companyData.ai_analysis.decision_result.key_factors?.slice(0, 4).map((factor, index) => (
                    <li key={index} className="flex items-start space-x-3">
                      <div className="w-2 h-2 bg-blue-400 rounded-full mt-2"></div>
                      <span className="text-sm text-gray-700">{factor}</span>
                    </li>
                  ))}
                </ul>
              </div>

              {companyData.ai_analysis.decision_result.reasoning && (
                <div className="bg-gradient-to-br from-amber-50 to-orange-50 p-6 rounded-xl border border-amber-200">
                  <h4 className="font-semibold text-amber-900 mb-4 text-lg">Detailed Reasoning</h4>
                  <div className="text-sm text-amber-800 whitespace-pre-line leading-relaxed">
                    {companyData.ai_analysis.decision_result.reasoning}
                  </div>
                </div>
              )}

              {companyData.ai_analysis.decision_result.recommended_actions && (
                <div className="bg-gradient-to-br from-green-50 to-emerald-50 p-6 rounded-xl border border-green-200">
                  <h4 className="font-semibold text-green-900 mb-4 text-lg">Recommended Actions</h4>
                  <ul className="space-y-3">
                    {companyData.ai_analysis.decision_result.recommended_actions.slice(0, 3).map((action, index) => (
                      <li key={index} className="flex items-start space-x-3">
                        <div className="text-green-500 mt-0.5 text-lg">→</div>
                        <span className="text-sm text-green-800">{action}</span>
                      </li>
                    ))}
                  </ul>
                </div>
              )}
            </div>
          </div>
        )}

        {/* Recommendation Details */}
        {recommendation && (
          <div className="bg-white rounded-lg shadow-md p-8 mb-8">
            <h3 className="text-xl font-bold text-gray-900 mb-6">Loan Recommendation Details</h3>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div>
                <h4 className="font-semibold text-gray-900 mb-4">Loan Terms</h4>
                <div className="space-y-3">
                  <div className="flex justify-between">
                    <span className="text-gray-600">Principal Amount</span>
                    <span className="font-medium text-gray-900">
                      {formatCurrency(recommendation.loan_limit)}
                    </span>
                  </div>
                  <div className="flex justify-between">
                    <span className="text-gray-600">Interest Rate</span>
                    <span className="font-medium text-gray-900">
                      {recommendation.interest_rate}% p.a.
                    </span>
                  </div>
                  <div className="flex justify-between">
                    <span className="text-gray-600">Tenure</span>
                    <span className="font-medium text-gray-900">
                      {recommendation.tenure_months} months
                    </span>
                  </div>
                </div>
              </div>
              <div>
                <h4 className="font-semibold text-gray-900 mb-4">Conditions</h4>
                <div className="space-y-2">
                  {recommendation.conditions?.map((condition, index) => (
                    <div
                      key={index}
                      className="flex items-start space-x-2 p-3 bg-yellow-50 rounded-lg"
                    >
                      <div className="w-2 h-2 bg-yellow-400 rounded-full mt-1.5"></div>
                      <p className="text-sm text-gray-700">{condition}</p>
                    </div>
                  ))}
                </div>
              </div>
            </div>

            <div className="mt-6 flex justify-center">
              <SimpleButton
                onClick={() => navigate('/cam-preview')}
                className="bg-green-600 hover:bg-green-700"
                size="lg"
              >
                Generate Full Report
              </SimpleButton>
            </div>
          </div>
        )}

        {/* Action Buttons */}
        <div className="mt-8 flex justify-center space-x-4">
          <SimpleButton
            onClick={() => navigate('/')}
            className="bg-gray-600 hover:bg-gray-700"
          >
            Upload New Documents
          </SimpleButton>
          <SimpleButton
            onClick={() => window.location.reload()}
            className="bg-yellow-500 hover:bg-yellow-600"
          >
            Refresh Analysis
          </SimpleButton>
        </div>
      </div>
    </div>
  );
};

export default SimpleDashboard;
